# Definition for a binary tree node.
class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def getMinimumDifference(self, root: TreeNode) -> int:
    self.prev = None
    self.best = float('inf')

    def inorder(node: TreeNode) -> None:
        if node is None:
            return
        inorder(node.left)                    # smaller values first
        if self.prev is not None:
            self.best = min(self.best, node.val - self.prev)  # adjacent gap
        self.prev = node.val                  # this node becomes the predecessor
        inorder(node.right)                   # larger values next

    inorder(root)
    return self.best

